const money=(n:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n||0);
const saleFinancials=(sale:Sale,items:SaleItemSummary[],returns:ReturnItemSummary[])=>{
 if(sale.status==='voided')return{netRevenue:0,cost:0,profit:0,margin:0};
 const rows=items.filter(x=>x.sale_id===sale.id);
 const gross=rows.reduce((a,x)=>a+x.qty*x.rate,0);
 const fullCost=rows.reduce((a,x)=>a+x.qty*x.purchase_rate_snapshot,0);
 const ids=new Set(rows.map(x=>x.id));
 const returned=returns.filter(x=>ids.has(x.sale_item_id));
 const returnedGross=returned.reduce((a,x)=>a+x.qty*x.rate,0);
 const byId=new Map(rows.map(x=>[x.id,x]));
 const returnedCost=returned.reduce((a,x)=>a+x.qty*(byId.get(x.sale_item_id)?.purchase_rate_snapshot||0),0);
 const ratio=gross>0?Math.min(1,returnedGross/gross):0;
 const netRevenue=Math.max(0,(sale.total||0)*(1-ratio));
 const cost=Math.max(0,fullCost-returnedCost);
 const profit=netRevenue-cost;
 return{netRevenue,cost,profit,margin:netRevenue>0?(profit/netRevenue)*100:0};
};
const aggregateFinancials=(sales:Sale[],items:SaleItemSummary[],returns:ReturnItemSummary[])=>{
 const active=sales.filter(s=>s.status!=='voided');
 const rows=active.map(s=>saleFinancials(s,items,returns));
 const netRevenue=rows.reduce((a,x)=>a+x.netRevenue,0),cost=rows.reduce((a,x)=>a+x.cost,0),profit=rows.reduce((a,x)=>a+x.profit,0);
 return{netRevenue,cost,profit,margin:netRevenue>0?(profit/netRevenue)*100:0};
};
