 const undoLast=async()=>{if(!savedSaleId||undoLeft<=0)return;setBusy(true);const{error}=await supabase.rpc('undo_sale',{p_sale_id:savedSaleId});if(error){setMsg(error.message);setCheckoutStage('idle')}else{await reload(true);resetBill();setMsg('Last bill undone. Stock restored successfully.')}setBusy(false)};
