 <div className="billing-layout"><section className="panel product-browser"><div className="billing-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search product, SKU or barcode…"/></div><div className="chips">{cats.map(c=><button key={c} className={cat===c?'active':''} onClick={()=>setCat(c)}>{c}</button>)}</div><div className="product-carousel-head"><div><b>Products</b><span>{visible.length} items</span></div><div className="carousel-controls"><button className="icon" aria-label="Previous products" onClick={()=>scrollProducts(-1)}><ChevronRight className="carousel-prev"/></button><button className="icon" aria-label="Next products" onClick={()=>scrollProducts(1)}><ChevronRight/></button></div></div><div className="product-grid product-carousel" ref={productCarousel}>{visible.map(p=><button className="product-card" key={p.id} onClick={()=>add(p)} disabled={p.current_stock<=0}><ProductIcon category={p.category}/><div><b>{p.name}</b><span>{p.brand||p.category}</span></div><div className="prod-bottom"><strong>{money(p.selling_rate)}</strong><small className={p.current_stock<=p.min_stock?'danger-text':''}>{p.current_stock}</small></div></button>)}</div></section><aside className="cart-panel"><div className="cart-title"><div><h3>Current Bill</h3><span>{cart.length} products</span></div><button className="btn soft" onClick={()=>setCart([])}><Trash2/>Clear</button></div><div className="cart-lines">{cart.map(x=><div className="cart-line" key={x.product.id}><div className="grow"><b>{x.product.name}</b><span>{money(x.product.selling_rate)} each</span></div><div className="qty"><button onClick={()=>upd(x.product.id,-1)}><Minus/></button><b>{x.qty}</b><button onClick={()=>upd(x.product.id,1)}><Plus/></button></div><strong>{money(x.qty*x.product.selling_rate)}</strong></div>)}{!cart.length&&<div className="empty-cart"><ShoppingCart/><b>Cart is empty</b><span>Tap a product to add it</span></div>}</div><div className="customer-box"><div className="section-label"><UserRound/> Customer (optional)</div><input list="customer-list" value={customer} onChange={e=>pickCustomer(e.target.value)} placeholder="Customer name"/><datalist id="customer-list">{customers.map(c=><option key={c.id} value={c.name}/>)}</datalist><input value={mobile} onChange={e=>setMobile(e.target.value)} placeholder="Mobile number"/></div><div className="service-mode"><span className="section-label">Order Type</span><div><button className={serviceMode==='parcel'?'active':''} onClick={()=>setServiceMode('parcel')}>Parcel</button><button className={serviceMode==='dine_in'?'active':''} onClick={()=>setServiceMode('dine_in')}>Dine In</button></div></div><div className="pay-types">{['cash','upi','card','credit'].map(x=><button key={x} onClick={()=>setPayment(x)} className={payment===x?'active':''}>{x.toUpperCase()}</button>)}</div><div className="totals"><div><span>Subtotal</span><b>{money(subtotal)}</b></div><div><span>Discount</span><div className="discount-input">₹<input value={discount} onChange={e=>setDiscount(e.target.value)}/></div></div><div className="grand"><span>Total</span><strong>{money(total)}</strong></div></div>{msg&&<div className="notice error">{msg}</div>}<button className="btn primary full big pay-button" disabled={!cart.length||busy} onClick={pay}><CheckCircle2/>{busy?'Saving Bill…':`Complete Bill • ${money(total)}`}</button></aside></div>
